/// Immutable snapshot data models for token streams.
library;

import 'token_stream_phase.dart';

/// An immutable snapshot representing the state of a token stream at a specific point in time.
class TokenStreamSnapshot {
  /// The current deterministic lifecycle phase of the stream.
  final TokenStreamPhase phase;

  /// The accumulated text generated by the stream so far.
  final String text;

  /// Transient reasoning or status message active only during the thinking phase.
  ///
  /// This value is automatically set to null once output tokens begin streaming
  /// or when the stream reaches a terminal phase.
  final String? reasoningStatus;

  /// The total number of token chunks processed so far.
  final int tokenCount;

  /// The duration elapsed since stream processing started.
  final Duration elapsed;

  /// The error object if the stream failed, or null otherwise.
  final Object? error;

  /// The stack trace associated with [error], or null if no error occurred.
  final StackTrace? stackTrace;

  /// Creates a new [TokenStreamSnapshot] instance with the specified values.
  const TokenStreamSnapshot({
    required this.phase,
    this.text = '',
    this.reasoningStatus,
    this.tokenCount = 0,
    this.elapsed = Duration.zero,
    this.error,
    this.stackTrace,
  });

  /// Creates an initial idle snapshot with default values.
  const TokenStreamSnapshot.idle()
      : this(
          phase: TokenStreamPhase.idle,
          text: '',
          reasoningStatus: null,
          tokenCount: 0,
          elapsed: Duration.zero,
          error: null,
          stackTrace: null,
        );

  /// Whether the stream is currently active (either thinking or streaming).
  bool get isActive =>
      phase == TokenStreamPhase.thinking || phase == TokenStreamPhase.streaming;

  /// Whether the stream is currently in the thinking phase.
  bool get isThinking => phase == TokenStreamPhase.thinking;

  /// Whether the stream is actively receiving output tokens.
  bool get isStreaming => phase == TokenStreamPhase.streaming;

  /// Whether the stream has reached a terminal state (completed, cancelled, or failed).
  bool get isTerminal =>
      phase == TokenStreamPhase.completed ||
      phase == TokenStreamPhase.cancelled ||
      phase == TokenStreamPhase.failed;

  /// Computes the throughput in tokens per second based on [tokenCount] and [elapsed].
  ///
  /// Returns `0.0` if [elapsed] is zero or negative.
  double get tokensPerSecond {
    final milliseconds = elapsed.inMilliseconds;
    if (milliseconds <= 0) {
      return 0.0;
    }
    return tokenCount / (milliseconds / 1000.0);
  }

  /// Creates a copy of this snapshot with the given fields replaced by new values.
  ///
  /// To explicitly clear [reasoningStatus], [error], or [stackTrace] to null,
  /// set [clearReasoningStatus], [clearError], or [clearStackTrace] to `true`.
  TokenStreamSnapshot copyWith({
    TokenStreamPhase? phase,
    String? text,
    String? reasoningStatus,
    bool clearReasoningStatus = false,
    int? tokenCount,
    Duration? elapsed,
    Object? error,
    bool clearError = false,
    StackTrace? stackTrace,
    bool clearStackTrace = false,
  }) {
    return TokenStreamSnapshot(
      phase: phase ?? this.phase,
      text: text ?? this.text,
      reasoningStatus: clearReasoningStatus
          ? null
          : (reasoningStatus ?? this.reasoningStatus),
      tokenCount: tokenCount ?? this.tokenCount,
      elapsed: elapsed ?? this.elapsed,
      error: clearError ? null : (error ?? this.error),
      stackTrace: clearStackTrace ? null : (stackTrace ?? this.stackTrace),
    );
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is TokenStreamSnapshot &&
        other.phase == phase &&
        other.text == text &&
        other.reasoningStatus == reasoningStatus &&
        other.tokenCount == tokenCount &&
        other.elapsed == elapsed &&
        other.error == error &&
        other.stackTrace == stackTrace;
  }

  @override
  int get hashCode => Object.hash(
        phase,
        text,
        reasoningStatus,
        tokenCount,
        elapsed,
        error,
        stackTrace,
      );

  @override
  String toString() {
    return 'TokenStreamSnapshot(phase: $phase, text: "$text", '
        'reasoningStatus: $reasoningStatus, tokenCount: $tokenCount, '
        'elapsed: $elapsed, error: $error)';
  }
}
